-- Artificial doctor and availability seed data for AI scheduling agent
-- Generated sample data only. Do not use as real medical data.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;

-- Minimal schema compatible with a PostgreSQL scheduling agent

CREATE TABLE IF NOT EXISTS departments (
  id UUID PRIMARY KEY,
  name VARCHAR(120) UNIQUE NOT NULL,
  description TEXT,
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS clinics (
  id UUID PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  city VARCHAR(80),
  area VARCHAR(100),
  address TEXT,
  phone VARCHAR(30),
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS doctors (
  id UUID PRIMARY KEY,
  full_name VARCHAR(160) NOT NULL,
  gender VARCHAR(20) CHECK (gender IN ('male','female','other')),
  department_id UUID REFERENCES departments(id),
  clinic_id UUID REFERENCES clinics(id),
  qualification VARCHAR(200),
  experience_years INT CHECK (experience_years >= 0),
  languages TEXT[],
  consultation_fee INT,
  rating NUMERIC(2,1),
  online_consultation BOOLEAN DEFAULT false,
  max_daily_appointments INT DEFAULT 16,
  preferred_patient_age_group VARCHAR(30) DEFAULT 'all',
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW()
);
CREATE TABLE IF NOT EXISTS doctor_availability (
  id UUID PRIMARY KEY,
  doctor_id UUID NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  day_of_week INT NOT NULL CHECK (day_of_week BETWEEN 1 AND 7),
  start_time TIME NOT NULL,
  end_time TIME NOT NULL,
  time_range VARCHAR(30),
  slot_duration_minutes INT NOT NULL DEFAULT 30,
  max_patients_per_slot INT NOT NULL DEFAULT 1,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW(),
  CHECK (start_time < end_time)
);
CREATE INDEX IF NOT EXISTS idx_doctors_department ON doctors(department_id);
CREATE INDEX IF NOT EXISTS idx_doctors_clinic ON doctors(clinic_id);
CREATE INDEX IF NOT EXISTS idx_doctors_languages ON doctors USING GIN(languages);
CREATE INDEX IF NOT EXISTS idx_doctor_availability_doctor_day ON doctor_availability(doctor_id, day_of_week);


